'use strict';
// Local, framework-free example library. Each record produces standalone source.
(() => {
  const families = {
    neumorphism:{name:'Neumorphism',light:['#e5eaf0','#e5eaf0','#202936','#455367','#235b87'],dark:['#242d39','#242d39','#f3f6fa','#c0ccdb','#9acbff'],radius:12,panelRadius:20,font:'ui-rounded, system-ui, sans-serif',guidance:'Soft paired shadows express raised and inset surfaces. Explicit boundaries and focus remain visible; shadows never carry state alone.'},
    glassmorphism:{name:'Glassmorphism',light:['#dcebf5','#f3f8fc','#12263a','#3c566d','#075f79'],dark:['#102535','#1c3a4d','#f0f8fc','#bfd7e5','#8ae5ef'],radius:12,panelRadius:16,font:'ui-monospace, monospace',guidance:'Translucency separates a foreground control surface from its backdrop. An opaque fallback preserves readability when blur is unavailable.'},
    flat:{name:'Flat',light:['#f4f7fc','#ffffff','#182336','#48586f','#2456b8'],dark:['#131d2d','#202f45','#f3f6fc','#bdcce2','#9dbfff'],radius:0,panelRadius:4,font:'ui-monospace, monospace',guidance:'Solid color, typography and whitespace establish hierarchy. No gradients or elevation are required.'},
    'semi-flat':{name:'Semi-flat',light:['#edf4f2','#ffffff','#15392f','#456057','#176653'],dark:['#112b24','#203e34','#effbf6','#b8d3c7','#8addb9'],radius:8,panelRadius:12,font:'ui-rounded, system-ui, sans-serif',guidance:'Small elevation and measured rounding distinguish actionable surfaces while retaining a simple, flat foundation.'},
    bubble:{name:'Bubble',light:['#eaf3ff','#ffffff','#142e56','#465c7e','#a51e59'],dark:['#152449','#26375f','#f5f8ff','#c4d4f3','#ffb2d0'],radius:24,panelRadius:32,font:'ui-rounded, system-ui, sans-serif',guidance:'Pill controls, inflated surfaces and tactile feedback make the interaction playful. Text labels and stable layouts remain primary.'},
    'neo-brutalism':{name:'Neo-brutalism',light:['#f2f3f5','#ffffff','#16191e','#484c54','#cce84f'],dark:['#181b20','#2a2f37','#ffffff','#c6ccd5','#d9ef78'],radius:0,panelRadius:4,font:'ui-monospace, monospace',guidance:'Bold labels, deliberate outlines and hard-offset shadows reveal the structure. Lime actions use dark text for contrast.'}
  };
  function tokens(id,appearance) {
    const f=families[id],light=appearance==='light',p=f[light?'light':'dark'];
    const raised=id==='neumorphism'?'8px 8px 20px var(--shade), -8px -8px 20px var(--shine)':id==='flat'?'none':id==='neo-brutalism'?'4px 4px 0 var(--edge)':id==='bubble'?'0 6px 0 var(--shade), inset 0 3px 0 var(--shine)':'0 4px 16px var(--shade)';
    return `--canvas:${p[0]};--surface:${p[1]};--text:${p[2]};--muted:${p[3]};--accent:${p[4]};--on-accent:${light&&id!=='neo-brutalism'?'#ffffff':'#102030'};--border:${p[3]};--focus:${light?'#173fa6':'#fff09b'};--error:${light?'#a31339':'#ffb9cc'};--shade:${light?'#23334430':'#00000066'};--shine:${light?'#ffffffb3':'#ffffff1f'};--edge:${light?'#16191e':'#ffffff'};--radius:${f.radius}px;--panel-radius:${f.panelRadius}px;--display:${f.font};--elevation:${raised};--line:${id==='neo-brutalism'?2:1}px;--wash:${light?'#accfef':'#1c5975'};color-scheme:${light?'light':'dark'};`;
  }
  const sharedCSS = `
*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:var(--s4);background:var(--canvas);color:var(--text);font:var(--body)/1.6 system-ui,sans-serif}
:root{--s1:4px;--s2:8px;--s3:12px;--s4:16px;--s6:24px;--s8:32px;--body:16px;--title:24px;--display-size:32px;--hit:44px;--fast:160ms;--enter:240ms;--focus-ring:2px solid var(--focus);--demo-width:720px}
.demo{width:min(100%,var(--demo-width));min-width:0;display:grid;gap:var(--s6)}.stack,.panel,form{display:grid;gap:var(--s4);min-width:0}.panel{padding:var(--s6);border-radius:var(--panel-radius);background:var(--surface);box-shadow:var(--elevation)}
h1,h2,h3,p{margin:0}h1,h2,h3{font-family:var(--display);line-height:1.25;overflow-wrap:anywhere}h1{font-size:var(--title)}h2{font-size:20px}h3{font-size:var(--body)}p{max-width:68ch;overflow-wrap:anywhere}small,.muted{color:var(--muted)}.eyebrow{font:600 var(--body)/1.4 var(--display);color:var(--accent)}
.row{display:flex;flex-wrap:wrap;align-items:center;gap:var(--s2);min-width:0}.between{justify-content:space-between}.grid{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--s4)}.grid>*{min-width:0}.stat{display:grid;gap:var(--s1)}.stat strong{font:700 clamp(24px,7vw,var(--display-size))/1.2 var(--display);white-space:nowrap}.stat span{display:block;color:var(--muted)}
button,input,textarea{font:inherit;color:inherit;border-radius:var(--radius)}button{display:inline-flex;align-items:center;justify-content:center;gap:var(--s2);min-width:var(--hit);min-height:var(--hit);padding:var(--s2) var(--s4);border:var(--line) solid var(--border);background:var(--surface);cursor:pointer;box-shadow:var(--elevation);touch-action:manipulation}
button.primary,button[aria-pressed=true]{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}button:active:not(:disabled){transform:translateY(2px)}button:disabled{cursor:not-allowed;border-style:dashed;color:var(--muted);box-shadow:none}button.primary:disabled{background:var(--surface)}
input,textarea{display:block;min-width:0;width:100%;max-width:100%;min-height:var(--hit);padding:var(--s2) var(--s3);border:var(--line) solid var(--border);background:var(--surface)}input[type=range]{padding:0;accent-color:var(--accent)}input[type=radio],input[type=checkbox]{width:var(--s6);min-height:var(--s6);height:var(--s6);accent-color:var(--accent);flex:none}label{display:grid;gap:var(--s2)}.choice{display:flex;align-items:center;gap:var(--s3);min-height:var(--hit);padding:var(--s2);cursor:pointer}.choice:has(input:checked){background:var(--canvas);border-radius:var(--radius)}
fieldset{min-width:0;padding:0;margin:0;border:0;display:grid;gap:var(--s2)}legend{padding:0;margin-bottom:var(--s2);font-weight:600}.error{color:var(--error)}[aria-invalid=true]{border-color:var(--error)}:focus-visible{outline:var(--focus-ring);outline-offset:var(--s1)}
.list{display:grid;gap:var(--s3);padding:0;margin:0;list-style:none}.item{display:grid;gap:var(--s2);padding:var(--s4);background:var(--canvas);border-radius:var(--radius)}.item p{color:var(--muted)}.pill{display:inline-flex;padding:var(--s1) var(--s3);border:var(--line) solid var(--border);border-radius:var(--radius);font-size:var(--body)}.status{min-height:1.6em;color:var(--muted)}
progress{display:block;width:100%;height:var(--s3);accent-color:var(--accent)}output{font:700 var(--display-size)/1.3 var(--display);white-space:nowrap}.timer{font-variant-numeric:tabular-nums;font-size:clamp(32px,12vw,64px)}
dialog{width:min(560px,calc(100% - var(--s8)));max-height:calc(100% - var(--s8));overflow:auto;border:var(--line) solid var(--border);border-radius:var(--panel-radius);padding:var(--s6);background:var(--surface);color:var(--text);box-shadow:var(--elevation)}dialog::backdrop{background:#0009}dialog[open]{animation:arrive var(--enter) ease-out}.command-list{display:grid;gap:var(--s2)}.command-list button{justify-content:flex-start}.summary{display:grid;gap:var(--s2);margin:0}.summary div{display:grid;gap:var(--s1)}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}[hidden]{display:none!important}
@keyframes arrive{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}@media(hover:hover){button:hover:not(:disabled){outline:1px solid var(--accent);outline-offset:var(--s1)}button:focus-visible{outline:var(--focus-ring)}}@media(pointer:coarse){:root{--hit:48px}}@media(min-width:600px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:360px){.panel{padding:var(--s4)}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}button:active:not(:disabled){transform:none}}
`;
  function familyCSS(id) {
    let extra='';
    if(id==='neumorphism') extra='input:not([type=radio]):not([type=checkbox]):not([type=range]){box-shadow:inset 4px 4px 8px var(--shade),inset -4px -4px 8px var(--shine)}button[aria-checked=true]{box-shadow:inset 4px 4px 8px var(--shade);color:var(--accent)}';
    if(id==='glassmorphism') extra='body{background:radial-gradient(ellipse at 10% 15%,var(--wash),transparent 60%),var(--canvas)}.panel{border:var(--line) solid var(--border)}@supports(backdrop-filter:blur(16px)){.panel{background:color-mix(in srgb,var(--surface) 92%,transparent);backdrop-filter:blur(16px)}}';
    if(id==='bubble') extra='h1{font-weight:800;letter-spacing:-.03em}.panel{border:var(--line) solid var(--border)}button{font-weight:700;border-radius:999px}.bubble-mark{display:grid;place-items:center;width:64px;height:64px;border-radius:50%;background:var(--accent);color:var(--on-accent);font:800 24px var(--display);box-shadow:var(--elevation)}';
    if(id==='neo-brutalism') extra='.panel{border:var(--line) solid var(--edge)}h1{font-weight:800;letter-spacing:-.04em}button{font-weight:700;border-color:var(--edge)}';
    return ':root{'+tokens(id,'dark')+'}\n:root[data-appearance=light]{'+tokens(id,'light')+'}\n'+sharedCSS+'\n'+extra+'\n:root[data-appearance=a11y]{--canvas:#000;--surface:#000;--text:#fff;--muted:#fff;--accent:#ffff00;--on-accent:#000;--border:#fff;--focus:#ffff00;--edge:#fff;--error:#ffb9cc;--elevation:none;--wash:#000;color-scheme:dark}\n[data-appearance=a11y] body,[data-appearance=a11y] .panel{background:var(--surface);backdrop-filter:none}[data-appearance=a11y] .panel{border:1px solid var(--border)}[data-appearance=a11y] button,[data-appearance=a11y] input{box-shadow:none}';
  }
  const helpers = `const $=selector=>document.querySelector(selector);\nconst $$=selector=>[...document.querySelectorAll(selector)];\nconst say=text=>{const node=$('#feedback');if(node)node.textContent=text;};\n`;
  const examples=[];
  function add(id,style,level,name,category,description,content,action,miniature,api,usage,css='') {
    examples.push({id,designStyle:style,level,name,category,description,tags:style+' '+level+' '+name.toLowerCase(),tier:'free',experimental:false,targetDevices:['mobile','tablet','laptop'],requirements:['Visible keyboard focus','Text-based state feedback','Reduced-motion fallback'],api,usage,miniature,
      html:'<main class="demo">\n  <header class="stack"><p class="eyebrow">'+families[style].name+' / '+level+'</p><h1>'+name+'</h1><p class="muted">'+description+'</p></header>\n'+content+'\n<p id="feedback" class="status" role="status">Ready to try. Changes stay in this example.</p>\n</main>',
      css:familyCSS(style)+'\n'+css,
      js:helpers+'('+action.toString()+')();'});
  }

  add('neo-power-switch','neumorphism','basic','Power switch','Actions','One clear control, with a state you can feel.',
    '<section class="panel"><p class="muted">Workspace lighting</p><button id="power" role="switch" aria-checked="false">Power off</button><p>Local control example; no device is connected.</p></section>',
    function(){const button=$('#power');button.onclick=()=>{const on=button.getAttribute('aria-checked')!=='true';button.setAttribute('aria-checked',String(on));button.textContent=on?'Power on':'Power off';say(on?'Lighting is on in this example.':'Lighting is off in this example.');};},
    '<span class="thumb-label">Workspace lighting</span><span class="thumb-pill">Power on</span>',
    [['aria-checked','Communicates the switch state.'],['click','Toggles locally; native button supports Space and Enter.']],
    'Use a stable switch name and explicit on/off text. The inset state supplements, rather than replaces, the semantic state.');

  add('neo-audio-panel','neumorphism','composite','Audio panel','Forms','Volume, mute and output, coordinated in one place.',
    '<section class="panel"><label for="volume">Volume</label><input id="volume" type="range" min="0" max="100" value="65"><output id="volume-value" for="volume">65%</output><button id="mute" aria-pressed="false">Mute</button><fieldset><legend>Output</legend><label class="choice"><input name="output" type="radio" value="Speakers" checked>Speakers</label><label class="choice"><input name="output" type="radio" value="Headphones">Headphones</label></fieldset><p class="muted">Interface only. No sound is played.</p></section>',
    function(){let muted=false;const update=()=>{$('#volume-value').textContent=(muted?0:$('#volume').value)+'%';$('#mute').setAttribute('aria-pressed',String(muted));$('#mute').textContent=muted?'Unmute':'Mute';say($('input[name=output]:checked').value+' · '+(muted?'Muted':$('#volume').value+'% volume'));};$('#volume').oninput=update;$('#mute').onclick=()=>{muted=!muted;update();};$$('input[name=output]').forEach(r=>r.onchange=update);},
    '<span class="thumb-label">VOLUME</span><strong class="thumb-value">65%</strong><span class="thumb-track"><i></i></span><span class="thumb-label">Speakers · Unmuted</span>',
    [['input[type=range]','Adjusts 0–100; keyboard arrow keys are native.'],['aria-pressed','Stores mute state without discarding volume.'],['name="output"','Exclusive output choice.']],
    'Keep output, level and mute independent. Unmuting restores the selected volume. This sample does not access audio hardware.');

  add('neo-focus-session','neumorphism','advanced','Focus session','Actions','A small timer with a complete start-to-finish flow.',
    '<section class="panel"><label for="minutes">Session length, minutes (1–60)</label><input id="minutes" type="number" min="1" max="60" value="1" required aria-describedby="duration-error"><p id="duration-error" class="error"></p><output id="clock" class="timer" role="timer">01:00</output><div class="row"><button id="start" class="primary">Start</button><button id="pause" disabled>Pause</button><button id="reset">Reset</button></div></section>',
    function(){let remaining=60,running=false,deadline=0,tick=null;const show=()=>{$('#clock').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');};const stop=()=>{clearInterval(tick);tick=null;running=false;};const valid=()=>{const input=$('#minutes');const ok=input.validity.valid&&Number.isInteger(Number(input.value));input.setAttribute('aria-invalid',String(!ok));$('#duration-error').textContent=ok?'':'Enter a whole number from 1 to 60.';return ok;};const controls=()=>{$('#minutes').disabled=running||$('#start').textContent==='Resume';$('#start').disabled=running;$('#pause').disabled=!running;};$('#minutes').onblur=()=>{if(valid()){remaining=Number($('#minutes').value)*60;show();}};$('#start').onclick=()=>{if(!valid()){$('#minutes').focus();return;}if($('#start').textContent!=='Resume')remaining=Number($('#minutes').value)*60;running=true;deadline=Date.now()+remaining*1000;controls();say('Focus session running.');tick=setInterval(()=>{remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));show();if(!remaining){stop();$('#start').textContent='Start again';controls();say('Session complete. Take a break.');}},250);};$('#pause').onclick=()=>{remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));stop();$('#start').textContent='Resume';controls();show();say('Paused. Resume when ready.');};$('#reset').onclick=()=>{stop();$('#start').textContent='Start';$('#minutes').disabled=false;remaining=valid()?Number($('#minutes').value)*60:60;controls();show();say('Timer reset.');};},
    '<span class="thumb-label">FOCUS SESSION</span><strong class="thumb-value">01:00</strong><div class="thumb-row"><span class="thumb-pill">Start</span><span>Pause</span></div>',
    [['deadline','Wall-clock deadline avoids accumulating timer drift.'],['Pause / Resume','Retains remaining seconds.'],['Reset','Stops the interval and restores the selected duration.']],
    'Announce start, pause and completion, not every second. This is an in-tab timer; it does not provide background notifications.');

  add('glass-segmented-control','glassmorphism','basic','Segmented control','Navigation','A translucent surface for related views.',
    '<section class="panel"><div class="row" role="group" aria-label="View"><button data-view="Overview" aria-pressed="true">Overview</button><button data-view="Activity" aria-pressed="false">Activity</button></div><h2 id="view-title">Overview</h2><p id="view-content">Keep the project essentials in view.</p></section>',
    function(){const buttons=$$('[data-view]');buttons.forEach((button,index)=>{button.onclick=()=>{buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$('#view-title').textContent=button.dataset.view;$('#view-content').textContent=index?'No recent changes in this local example.':'Keep the project essentials in view.';say(button.dataset.view+' selected.');};button.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();buttons[next].click();}};});},
    '<div class="thumb-row"><span class="thumb-pill">Overview</span><span>Activity</span></div><span class="thumb-line"></span><span class="thumb-line short"></span>',
    [['aria-pressed','Indicates the selected view.'],['Arrow keys / Home / End','Move between the choices and activate a view.']],
    'Use a short group of mutually exclusive views. Transparency is a surface treatment, not a reason to reduce text contrast.');

  add('glass-notification-center','glassmorphism','composite','Notification center','Disclosure','Read status and filters that stay in sync.',
    '<section class="panel"><div class="row between"><h2>Notifications</h2><span id="unread">2 unread</span></div><div class="row"><button data-filter="all" aria-pressed="true">All</button><button data-filter="unread" aria-pressed="false">Unread</button><button id="read-all">Mark all read</button></div><ul id="notifications" class="list"></ul><p id="empty" hidden>All caught up. Switch to All to see read messages.</p><button id="restore">Restore samples</button></section>',
    function(){const notices=[{title:'Review requested',body:'The form pattern is ready for your feedback.',read:false},{title:'New example',body:'A new interaction is available to explore.',read:false},{title:'Welcome',body:'Your local workspace is ready.',read:true}];let filter='all';const render=()=>{const list=$('#notifications');list.replaceChildren();notices.forEach((n,i)=>{if(filter==='unread'&&n.read)return;const li=document.createElement('li');li.className='item';const h=document.createElement('h3');h.textContent=n.title;const p=document.createElement('p');p.textContent=n.body;const button=document.createElement('button');button.textContent=n.read?'Read':'Mark as read';button.disabled=n.read;button.onclick=()=>{n.read=true;render();$('[data-filter="'+filter+'"]').focus();say(n.title+' marked as read.');};li.append(h,p,button);list.append(li);});const count=notices.filter(n=>!n.read).length;$('#unread').textContent=count+' unread';$('#empty').hidden=list.children.length>0;$('#read-all').disabled=count===0;};$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();say('Showing '+filter+' notifications.');});$('#read-all').onclick=()=>{notices.forEach(n=>n.read=true);render();say('All notifications marked as read.');};$('#restore').onclick=()=>{notices.forEach((n,i)=>n.read=i===2);render();say('Sample notifications restored.');};render();},
    '<div class="thumb-row"><strong>Inbox</strong><span class="thumb-pill">2 unread</span></div><span class="thumb-line"></span><span class="thumb-line short"></span>',
    [['read','Local state for each sample notification.'],['filter','All or unread without losing read state.'],['Restore samples','Restores the initial sample data.']],
    'Keep the read count and visible list consistent. The restore action makes the empty state reversible; no server is contacted.');

  add('glass-command-palette','glassmorphism','advanced','Command palette','Navigation','Find an action without losing your context.',
    '<section class="panel"><p>Search a small local command collection.</p><button id="open-command" class="primary">Open commands</button></section><dialog id="palette" aria-labelledby="palette-title"><div class="stack"><div class="row between"><h2 id="palette-title">Commands</h2><button id="close-command">Close</button></div><label for="command-query">Search commands</label><input id="command-query" type="search" autocomplete="off"><div id="command-list" class="command-list"></div><p id="command-empty" hidden>No commands found. Try a shorter query.</p><p class="muted">Arrow keys navigate. Enter selects. Escape closes.</p></div></dialog>',
    function(){const dialog=$('#palette'),query=$('#command-query');const commands=['Create a draft','Open local settings','View design tokens','Start a focus session'];const draw=()=>{const list=$('#command-list');list.replaceChildren();commands.filter(c=>c.toLowerCase().includes(query.value.toLowerCase())).forEach(name=>{const button=document.createElement('button');button.textContent=name;button.onclick=()=>{say(name+' selected. This is a local command demonstration.');dialog.close();};list.append(button);});$('#command-empty').hidden=list.children.length>0;};$('#open-command').onclick=()=>{query.value='';draw();dialog.showModal();query.focus();};$('#close-command').onclick=()=>dialog.close();dialog.addEventListener('close',()=>$('#open-command').focus());query.oninput=draw;dialog.onkeydown=e=>{const buttons=$$('#command-list button');if(!buttons.length)return;const index=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus();}else if(e.key==='Enter'&&document.activeElement===query){e.preventDefault();buttons[0].click();}};},
    '<span class="thumb-label">Find an action…</span><span class="thumb-pill">Create a draft</span><span class="thumb-label">Open local settings</span>',
    [['showModal()','Opens a modal dialog with native focus containment.'],['query','Filters the local command collection.'],['close','Returns focus to the opener.']],
    'Keep command actions local and predictable. Provide an explicit trigger and close button; shortcuts must never be the only path.');

  add('flat-quantity-stepper','flat','basic','Quantity stepper','Forms','A bounded number with clear limits.',
    '<section class="panel"><p id="quantity-label">Quantity, 1–10</p><div class="row" role="group" aria-labelledby="quantity-label"><button id="minus" aria-label="Decrease quantity" disabled>−</button><output id="quantity" aria-live="polite">1</output><button id="plus" aria-label="Increase quantity">+</button></div></section>',
    function(){let n=1;const draw=()=>{$('#quantity').textContent=n;$('#minus').disabled=n===1;$('#plus').disabled=n===10;say(n===10?'Maximum quantity reached.':n===1?'Minimum quantity reached.':'Quantity updated.');};$('#minus').onclick=()=>{n=Math.max(1,n-1);draw();};$('#plus').onclick=()=>{n=Math.min(10,n+1);draw();};},
    '<span class="thumb-label">QUANTITY</span><div class="thumb-row"><span class="thumb-pill">−</span><strong class="thumb-value">3</strong><span class="thumb-pill">+</span></div>',
    [['Minimum / maximum','Clamp the quantity between 1 and 10.'],['disabled','Prevents actions beyond the bounds.']],
    'Use for small bounded quantities. Keep the value readable and give symbol-only actions explicit accessible names.');

  add('flat-filter-list','flat','composite','Filterable list','Data display','Search and status filters working together.',
    '<section class="panel"><label for="task-search">Search tasks</label><input id="task-search" type="search" placeholder="Try documentation"><div class="row"><button data-status="all" aria-pressed="true">All</button><button data-status="open" aria-pressed="false">Open</button><button data-status="done" aria-pressed="false">Done</button></div><p id="task-count" role="status"></p><ul id="tasks" class="list"></ul><p id="no-tasks" hidden>No tasks match. Clear the search or change status.</p><button id="clear-task-filters">Clear filters</button></section>',
    function(){const tasks=[['Write documentation','open'],['Define tokens','done'],['Review keyboard flow','open']];let status='all';const draw=()=>{const found=tasks.filter(([title,s])=>(status==='all'||s===status)&&title.toLowerCase().includes($('#task-search').value.toLowerCase()));$('#tasks').replaceChildren();found.forEach(([title,s])=>{const li=document.createElement('li');li.className='item';li.textContent=title+' — '+s;$('#tasks').append(li);});$('#task-count').textContent=found.length+' tasks';$('#no-tasks').hidden=found.length>0;};$('#task-search').oninput=draw;$$('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;$$('[data-status]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));draw();});$('#clear-task-filters').onclick=()=>{status='all';$('#task-search').value='';$$('[data-status]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.status===status)));draw();$('#task-search').focus();};draw();},
    '<span class="thumb-label">Search tasks</span><div class="thumb-row"><span class="thumb-pill">All</span><span>Open</span><span>Done</span></div><span class="thumb-line"></span>',
    [['query + status','Both conditions must match.'],['Result count','Announces the visible result total.'],['Clear filters','Restores all sample tasks.']],
    'Keep query and filter state separate and provide recovery from zero results. These are illustrative local tasks.');

  add('flat-project-wizard','flat','advanced','Project wizard','Forms','Set up, review and finish without losing your input.',
    '<form id="wizard" class="panel" novalidate><p id="step-label" class="eyebrow">Step 1 of 3</p><section data-step="0" class="stack"><h2 tabindex="-1">Name your project</h2><label for="project-name">Project name (required)</label><input id="project-name" required minlength="2" maxlength="60" aria-describedby="name-error"><p id="name-error" class="error"></p></section><section data-step="1" class="stack" hidden><h2 tabindex="-1">Choose visibility</h2><fieldset><legend>Visibility</legend><label class="choice"><input type="radio" name="visibility" value="Private" checked>Private</label><label class="choice"><input type="radio" name="visibility" value="Team">Team</label></fieldset></section><section data-step="2" class="stack" hidden><h2 tabindex="-1">Review</h2><p id="project-summary"></p><p class="muted">Confirmation creates no real account or project.</p></section><div id="wizard-actions" class="row"><button type="button" id="wizard-back" hidden>Back</button><button id="wizard-next" class="primary">Continue</button></div><button id="wizard-restart" type="button" hidden>Start again</button></form>',
    function(){let step=0;const valid=()=>{const field=$('#project-name');const ok=field.value.trim().length>=2;field.setAttribute('aria-invalid',String(!ok));$('#name-error').textContent=ok?'':'Enter a project name with at least 2 characters.';return ok;};const draw=()=>{$$('[data-step]').forEach(s=>s.hidden=Number(s.dataset.step)!==step);$('#step-label').textContent='Step '+(step+1)+' of 3';$('#wizard-back').hidden=step===0;$('#wizard-next').textContent=step===2?'Confirm':'Continue';$('#project-summary').textContent=$('#project-name').value.trim()+' · '+$('input[name=visibility]:checked').value;$('[data-step="'+step+'"] h2').focus();};$('#project-name').onblur=valid;$('#wizard').onsubmit=e=>{e.preventDefault();if(step===0&&!valid()){$('#project-name').focus();return;}if(step<2){step++;draw();}else{$('#wizard-actions').hidden=true;$('#wizard-restart').hidden=false;$('#wizard-restart').focus();say('Project setup complete in this local example.');}};$('#wizard-back').onclick=()=>{step=Math.max(0,step-1);draw();};$('#wizard-restart').onclick=()=>{$('#wizard').reset();step=0;$('#wizard-actions').hidden=false;$('#wizard-restart').hidden=true;$('#project-name').removeAttribute('aria-invalid');$('#name-error').textContent='';draw();say('Ready for another project.');};},
    '<div class="thumb-row"><span class="thumb-pill">1</span><span>2</span><span>3</span></div><strong>Project setup</strong><span class="thumb-line"></span><span class="thumb-pill">Continue</span>',
    [['step','Tracks setup, options and review.'],['Back','Preserves entered data.'],['submit','Validates locally and advances or confirms.']],
    'Use explicit progress and preserve form values when moving backward. Completion is a local prototype state, not a backend request.');

  add('semiflat-save-action','semi-flat','basic','Save action','Actions','Ready, busy and saved with honest local feedback.',
    '<section class="panel"><p>Save your local sample preferences.</p><div class="row"><button id="save-local" class="primary">Save changes</button><button id="retry-local" disabled>Reset</button></div></section>',
    function(){let pending;$('#save-local').onclick=()=>{const b=$('#save-local');b.disabled=true;b.setAttribute('aria-busy','true');b.textContent='Saving…';say('Applying local changes…');pending=setTimeout(()=>{b.removeAttribute('aria-busy');b.textContent='Saved';$('#retry-local').disabled=false;say('Saved in this example. No data was sent.');},650);};$('#retry-local').onclick=()=>{clearTimeout(pending);const b=$('#save-local');b.disabled=false;b.removeAttribute('aria-busy');b.textContent='Save changes';$('#retry-local').disabled=true;b.focus();say('Ready to save again.');};},
    '<span class="thumb-label">LOCAL PREFERENCES</span><span class="thumb-pill">Save changes</span><span class="thumb-label">Ready to save</span>',
    [['aria-busy','Indicates the simulated save operation.'],['disabled','Prevents duplicate activation.'],['Reset','Restores the ready state.']],
    'Communicate a wait and a definite result. This timer demonstrates feedback and performs no network or persistent storage operation.');

  add('semiflat-plan-picker','semi-flat','composite','Plan picker','Forms','Choose a sample tier and see a consistent summary.',
    '<section class="panel"><p class="muted">Illustrative plans; no purchase is available.</p><fieldset><legend>Tier</legend><label class="choice"><input name="plan" type="radio" value="Starter" data-price="12" checked>Starter</label><label class="choice"><input name="plan" type="radio" value="Team" data-price="24">Team</label></fieldset><fieldset><legend>Billing period</legend><label class="choice"><input name="billing" type="radio" value="monthly" checked>Monthly</label><label class="choice"><input name="billing" type="radio" value="yearly">Yearly</label></fieldset><div class="stat"><strong id="plan-total">$12 / month</strong><span id="plan-summary">Starter · monthly</span></div></section>',
    function(){const draw=()=>{const p=$('input[name=plan]:checked'),year=$('input[name=billing]:checked').value==='yearly';const total=Number(p.dataset.price)*(year?12:1);$('#plan-total').textContent='$'+total+' / '+(year?'year':'month');$('#plan-summary').textContent=p.value+' · '+(year?'Yearly':'Monthly')+' · Sample pricing';say('Sample total updated; no payment is connected.');};$$('input').forEach(r=>r.onchange=draw);},
    '<span class="thumb-label">SAMPLE PLAN</span><strong>Starter</strong><strong class="thumb-value">$12</strong><span class="thumb-label">per month · example</span>',
    [['plan','Starter or Team sample tier.'],['billing','Monthly or yearly total.'],['data-price','Illustrative monthly price, not a commercial offer.']],
    'Keep the billing period attached to the total. Prices are sample values and there is no checkout or entitlement behavior.');

  add('semiflat-task-board','semi-flat','advanced','Task board','Data display','Create, move and undo with one shared task state.',
    '<section class="panel"><form id="new-task" novalidate><label for="new-title">Task title (required)</label><input id="new-title" required maxlength="80" aria-describedby="task-error"><p id="task-error" class="error"></p><button class="primary">Add task</button></form><p id="board-count"></p><div id="board" class="grid"></div><div class="row"><button id="undo-delete" disabled>Undo delete</button></div></section>',
    function(){let nextId=3,removed=null;const tasks=[{id:1,title:'Define component tokens',status:0},{id:2,title:'Write usage notes',status:1}];const stages=['To do','Doing','Done'];const draw=()=>{const board=$('#board');board.replaceChildren();stages.forEach((stage,index)=>{const col=document.createElement('section');col.className='stack';const h=document.createElement('h2');h.textContent=stage+' · '+tasks.filter(t=>t.status===index).length;col.append(h);tasks.filter(t=>t.status===index).forEach(task=>{const item=document.createElement('div');item.className='item';const title=document.createElement('h3');title.textContent=task.title;const actions=document.createElement('div');actions.className='row';const move=document.createElement('button');move.textContent=index===2?'Reopen':'Move to '+stages[index+1];move.onclick=()=>{task.status=(index+1)%3;draw();$('#new-title').focus();say(task.title+' moved to '+stages[task.status]+'.');};const del=document.createElement('button');del.textContent='Delete';del.setAttribute('aria-label','Delete '+task.title);del.onclick=()=>{removed={task,index:tasks.indexOf(task)};tasks.splice(removed.index,1);draw();$('#undo-delete').focus();say('Task deleted. Undo restores the latest deletion.');};actions.append(move,del);item.append(title,actions);col.append(item);});if(!tasks.some(t=>t.status===index)){const empty=document.createElement('p');empty.className='muted';empty.textContent='No tasks here.';col.append(empty);}board.append(col);});$('#board-count').textContent=tasks.length+' tasks · '+tasks.filter(t=>t.status===2).length+' done';$('#undo-delete').disabled=!removed;};const validate=()=>{const ok=$('#new-title').value.trim().length>0;$('#new-title').setAttribute('aria-invalid',String(!ok));$('#task-error').textContent=ok?'':'Enter a task title before adding it.';return ok;};$('#new-title').onblur=validate;$('#new-task').onsubmit=e=>{e.preventDefault();if(!validate()){$('#new-title').focus();return;}tasks.push({id:nextId++,title:$('#new-title').value.trim(),status:0});$('#new-title').value='';draw();$('#new-title').focus();say('Task added to To do.');};$('#undo-delete').onclick=()=>{if(!removed)return;tasks.splice(removed.index,0,removed.task);removed=null;draw();$('#new-title').focus();say('Deleted task restored.');};draw();},
    '<div class="thumb-row"><span class="thumb-pill">To do</span><span>Doing</span><span>Done</span></div><span class="thumb-line"></span><span class="thumb-line short"></span>',
    [['task.status','To do, Doing or Done.'],['Move buttons','Keyboard and touch alternative to drag-and-drop.'],['Undo delete','Restores the latest removed task and position.']],
    'Expose explicit move controls instead of requiring dragging. Task data lives only in the iframe; reset or reload restores samples.');

  add('bubble-reaction-picker','bubble','basic','Reaction picker','Actions','A playful choice, with words as well as shape.',
    '<section class="panel"><h2>How did that feel?</h2><div class="row" role="group" aria-label="Reaction"><button data-reaction="Helpful" aria-pressed="false">Helpful</button><button data-reaction="Surprising" aria-pressed="false">Surprising</button><button data-reaction="Fun" aria-pressed="false">Fun</button></div><p>Choose again to clear your reaction.</p></section>',
    function(){let selected='';$$('[data-reaction]').forEach(b=>b.onclick=()=>{selected=selected===b.dataset.reaction?'':b.dataset.reaction;$$('[data-reaction]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.reaction===selected)));say(selected?'Reaction: '+selected+'.':'Reaction cleared.');});},
    '<strong>How did that feel?</strong><div class="thumb-row"><span class="thumb-pill">Fun</span><span class="thumb-pill secondary">Helpful</span></div>',
    [['aria-pressed','Communicates the selected reaction.'],['Repeated activation','Clears the selected value.']],
    'Use concise words rather than unexplained symbols. Shape and pressed feedback add playfulness without hiding the meaning.');

  add('bubble-level-picker','bubble','composite','Level picker','Navigation','Explore available stages and understand what is locked.',
    '<section class="panel"><fieldset><legend>Choose a sample level</legend><div class="row"><button data-level="1" aria-pressed="true">Level 1</button><button data-level="2" aria-pressed="false">Level 2</button><button data-level="3" aria-pressed="false">Level 3</button><button disabled aria-describedby="locked-help">Level 4 · Locked</button></div></fieldset><p id="locked-help">Level 4 is locked in this sample. No unlock or payment is connected.</p><div class="bubble-mark" id="level-number" aria-hidden="true">1</div><h2 id="level-name">First steps</h2><p id="level-detail">Explore the controls at your own pace.</p><button id="choose-level" class="primary">Choose level</button></section>',
    function(){const names=['First steps','Find your rhythm','A new challenge'],descriptions=['Explore the controls at your own pace.','Coordinate a few choices together.','Follow a short sequence to the end.'];let selected=1;$$('[data-level]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.level);$$('[data-level]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#level-number').textContent=selected;$('#level-name').textContent=names[selected-1];$('#level-detail').textContent=descriptions[selected-1];say('Level '+selected+' selected.');});$('#choose-level').onclick=()=>say('Level '+selected+' chosen in this interface example. No game is launched.');},
    '<span class="thumb-label">CHOOSE A LEVEL</span><div class="thumb-row"><span class="thumb-pill">1</span><span class="thumb-pill secondary">2</span><span class="thumb-pill secondary">3</span></div><span>First steps</span>',
    [['selected','One of three available sample levels.'],['disabled','Locked choice with a visible explanation.'],['Choose level','Confirms the choice locally.']],
    'Explain unavailable choices in visible text. Choosing a sample level is not a real game launch or unlock.');

  add('bubble-quest-flow','bubble','advanced','Quest flow','Actions','A short journey from start to completion.',
    '<section class="panel"><div class="bubble-mark" aria-hidden="true">Q</div><h2 id="quest-heading" tabindex="-1">A little quest</h2><p id="quest-description">Complete three local tasks, one step at a time.</p><progress id="quest-progress" value="0" max="3" aria-label="Completed quest tasks"></progress><p id="quest-count">0 of 3 complete</p><div id="quest-start"><button id="begin-quest" class="primary">Start quest</button></div><div id="quest-task" class="stack" hidden><p id="quest-prompt"></p><button id="complete-task" class="primary">Complete task</button></div><button id="replay-quest" hidden>Replay</button></section>',
    function(){let done=0;const prompts=['Notice one useful detail in this interface.','Try reaching the action using your keyboard or touch.','Choose one pattern you would reuse.'];const draw=()=>{$('#quest-progress').value=done;$('#quest-count').textContent=done+' of 3 complete';$('#quest-task').hidden=done===3;$('#replay-quest').hidden=done!==3;if(done<3){$('#quest-prompt').textContent=prompts[done];$('#complete-task').textContent='Complete task '+(done+1);$('#complete-task').focus();}else{$('#quest-heading').textContent='Quest complete';$('#quest-description').textContent='Three small steps, one complete flow.';$('#replay-quest').focus();}say(done===3?'Quest complete. You can replay.':'Task '+(done+1)+' is ready.');};$('#begin-quest').onclick=()=>{$('#quest-start').hidden=true;draw();};$('#complete-task').onclick=()=>{done=Math.min(3,done+1);draw();};$('#replay-quest').onclick=()=>{done=0;$('#quest-heading').textContent='A little quest';$('#quest-description').textContent='Complete three local tasks, one step at a time.';draw();};},
    '<strong>Little quest</strong><strong class="thumb-value">2 / 3</strong><span class="thumb-track"><i></i></span><span class="thumb-pill">Continue</span>',
    [['progress','Completed task count from 0 to 3.'],['Complete task','Advances one task at a time.'],['Replay','Restarts the local journey.']],
    'Make progress understandable without animation. Each step is acknowledged by the user; no achievement or reward is persisted.');

  add('brutal-counter','neo-brutalism','basic','Counter','Actions','Direct controls. An unmistakable value.',
    '<section class="panel"><p id="counter-label">Count, 0–20</p><output id="count" aria-live="polite">0</output><div class="row" role="group" aria-labelledby="counter-label"><button id="decrement" disabled>Subtract</button><button id="increment" class="primary">Add one</button><button id="zero">Reset</button></div></section>',
    function(){let count=0;const draw=()=>{$('#count').textContent=count;$('#decrement').disabled=count===0;$('#increment').disabled=count===20;say('Count is '+count+(count===20?'. Maximum reached.':'.'));};$('#decrement').onclick=()=>{count=Math.max(0,count-1);draw();};$('#increment').onclick=()=>{count=Math.min(20,count+1);draw();};$('#zero').onclick=()=>{count=0;draw();};},
    '<span class="thumb-label">KEEP COUNT</span><strong class="thumb-value">07</strong><span class="thumb-pill">ADD ONE</span>',
    [['count','Integer bounded from 0 to 20.'],['Reset','Restores zero without a page reload.']],
    'A strong visual hierarchy can be direct without becoming noisy. Keep bounds explicit and disabled controls legible.');

  add('brutal-poll','neo-brutalism','composite','Poll','Forms','Choose, vote and reconsider in a local sample.',
    '<form id="poll" class="panel" novalidate><fieldset id="poll-options"><legend>Which pattern should come next?</legend><label class="choice"><input type="radio" name="vote" value="Navigation">Navigation</label><label class="choice"><input type="radio" name="vote" value="Forms">Forms</label><label class="choice"><input type="radio" name="vote" value="Data display">Data display</label></fieldset><p id="vote-error" class="error" role="alert"></p><button id="vote-submit" class="primary">Vote locally</button><div id="poll-results" class="stack" hidden></div><button type="button" id="change-vote" hidden>Change vote</button><p class="muted">Illustrative starting counts. Your vote is only stored in this example.</p></form>',
    function(){const baseline=[['Navigation',4],['Forms',3],['Data display',2]];$('#poll').onsubmit=e=>{e.preventDefault();const selected=$('input[name=vote]:checked');if(!selected){$('#vote-error').textContent='Choose an option before voting.';$('input[name=vote]').focus();return;}$('#vote-error').textContent='';$('#poll-results').replaceChildren();baseline.forEach(([label,n])=>{const count=n+(selected.value===label?1:0);const row=document.createElement('div');row.className='stack';const p=document.createElement('p');p.textContent=label+' · '+count+' sample votes';const meter=document.createElement('progress');meter.max=10;meter.value=count;meter.setAttribute('aria-label',label+' sample votes');row.append(p,meter);$('#poll-results').append(row);});$('#poll-options').disabled=true;$('#poll-results').hidden=false;$('#vote-submit').hidden=true;$('#change-vote').hidden=false;$('#change-vote').focus();say('Your local vote: '+selected.value+'.');};$('#change-vote').onclick=()=>{$('#poll-options').disabled=false;$('#poll-results').hidden=true;$('#vote-submit').hidden=false;$('#change-vote').hidden=true;$('input[name=vote]:checked').focus();say('Choose again. The previous local vote will be replaced.');};},
    '<strong>WHAT NEXT?</strong><span class="thumb-pill">Navigation</span><span class="thumb-track"><i></i></span><span class="thumb-label">Sample poll</span>',
    [['vote','Exactly one selected option.'],['baseline','Explicit illustrative counts, not real analytics.'],['Change vote','Replaces rather than accumulates the local vote.']],
    'Label sample results clearly. Let users reconsider without counting the same person multiple times in the local demonstration.');

  add('brutal-ticket-builder','neo-brutalism','advanced','Ticket builder','Forms','Configure, review and confirm a sample reservation.',
    '<form id="ticket-form" class="panel" novalidate><p class="muted">Demo event. No payment or reservation is made.</p><section id="ticket-config" class="stack"><fieldset><legend>Ticket type</legend><label class="choice"><input type="radio" name="ticket" value="Workshop" data-price="20" checked>Workshop · $20 sample</label><label class="choice"><input type="radio" name="ticket" value="Full day" data-price="40">Full day · $40 sample</label></fieldset><label for="ticket-quantity">Quantity (1–6)</label><input id="ticket-quantity" type="number" min="1" max="6" value="1" required aria-describedby="quantity-error"><p class="error" id="quantity-error"></p><label for="attendee">Attendee name (required)</label><input id="attendee" required maxlength="80" aria-describedby="attendee-error"><p class="error" id="attendee-error"></p><label for="attendee-email">Email (required)</label><input id="attendee-email" type="email" required aria-describedby="email-error"><p class="error" id="email-error"></p></section><section id="ticket-review" class="stack" hidden><h2 tabindex="-1">Review your selection</h2><p id="ticket-summary"></p><p id="attendee-summary"></p></section><p id="ticket-total"></p><div class="row"><button type="button" id="ticket-edit" hidden>Edit</button><button id="ticket-submit" class="primary">Review</button><button type="button" id="ticket-reset">Reset</button></div></form>',
    function(){let reviewing=false,confirmed=false;const fields=[['ticket-quantity','quantity-error','Enter a whole quantity from 1 to 6.'],['attendee','attendee-error','Enter an attendee name.'],['attendee-email','email-error','Enter a valid email, such as you@example.com.']];const validate=([id,error,message])=>{const input=$('#'+id);const ok=input.validity.valid&&input.value.trim().length>0&&(id!=='ticket-quantity'||Number.isInteger(Number(input.value)));input.setAttribute('aria-invalid',String(!ok));$('#'+error).textContent=ok?'':message;return ok;};fields.forEach(f=>$('#'+f[0]).onblur=()=>validate(f));const total=()=>{const qty=Number($('#ticket-quantity').value),price=Number($('input[name=ticket]:checked').dataset.price);$('#ticket-total').textContent=Number.isInteger(qty)&&qty>=1&&qty<=6?'Sample total: $'+qty*price:'Enter a valid quantity to calculate the total.';};$$('input[name=ticket]').forEach(r=>r.onchange=total);$('#ticket-quantity').oninput=total;const edit=()=>{reviewing=false;confirmed=false;$('#ticket-config').hidden=false;$('#ticket-review').hidden=true;$('#ticket-edit').hidden=true;$('#ticket-submit').hidden=false;$('#ticket-submit').textContent='Review';};$('#ticket-form').onsubmit=e=>{e.preventDefault();if(confirmed)return;if(!reviewing){const results=fields.map(validate);if(results.includes(false)){$('#'+fields[results.indexOf(false)][0]).focus();return;}reviewing=true;$('#ticket-config').hidden=true;$('#ticket-review').hidden=false;$('#ticket-summary').textContent=$('input[name=ticket]:checked').value+' × '+$('#ticket-quantity').value;$('#attendee-summary').textContent=$('#attendee').value.trim()+' · '+$('#attendee-email').value;$('#ticket-edit').hidden=false;$('#ticket-submit').textContent='Confirm locally';$('#ticket-review h2').focus();}else{confirmed=true;$('#ticket-submit').hidden=true;$('#ticket-reset').focus();say('Sample reservation confirmed locally. No ticket was issued and no data was sent.');}};$('#ticket-edit').onclick=()=>{edit();$('#attendee').focus();say('Edit your selection.');};$('#ticket-reset').onclick=()=>{$('#ticket-form').reset();edit();fields.forEach(([id,error])=>{$('#'+id).removeAttribute('aria-invalid');$('#'+error).textContent='';});total();$('input[name=ticket]').focus();say('Ticket builder reset.');};total();},
    '<span class="thumb-label">DEMO EVENT</span><strong>WORKSHOP</strong><div class="thumb-row"><span class="thumb-pill">2 tickets</span><span>$40 sample</span></div><span class="thumb-line short"></span>',
    [['Configuration','Ticket type, bounded quantity and attendee fields.'],['Review','Summarizes retained inputs before confirmation.'],['Confirm locally','Produces only a local example result.']],
    'Separate configuration, review and confirmation. Validate on blur and submission; errors stay beside their fields. Never imply a real purchase.');

  const miniatureCSS = Object.keys(families).map(id=>'.sample-thumb.sample-'+id+'{'+tokens(id,'light')+'}').join('\n')+`
.sample-thumb{display:grid;align-content:center;gap:var(--s3);min-height:240px;padding:var(--s6);background:var(--canvas);color:var(--text);font:14px/1.5 system-ui,sans-serif;min-width:0}
.sample-kicker{display:block;font:600 12px/1.4 var(--display);letter-spacing:.04em;color:var(--muted)}.sample-surface{display:grid;gap:var(--s3);padding:var(--s4);min-width:0;background:var(--surface);border-radius:var(--panel-radius);box-shadow:var(--elevation)}.sample-surface>*{min-width:0}.sample-thumb strong{font-family:var(--display)}.sample-thumb .thumb-value{display:block;font-size:32px;line-height:1.15;white-space:nowrap}.thumb-row{display:flex;flex-wrap:wrap;align-items:center;gap:var(--s2)}.thumb-label{display:block;color:var(--muted)}.thumb-pill{display:inline-flex;align-items:center;justify-content:center;justify-self:start;min-height:36px;padding:var(--s2) var(--s3);background:var(--accent);color:var(--on-accent);border:var(--line) solid var(--border);border-radius:var(--radius);font-weight:600;box-shadow:var(--elevation)}.thumb-pill.secondary{background:var(--surface);color:var(--text)}.thumb-line{display:block;height:8px;background:var(--border);opacity:.4;border-radius:var(--radius)}.thumb-line.short{width:65%}.thumb-track{display:block;height:12px;background:var(--canvas);border:1px solid var(--border);border-radius:var(--radius)}.thumb-track i{display:block;width:65%;height:100%;background:var(--accent);border-radius:inherit}.sample-glassmorphism{background:radial-gradient(ellipse at 15% 0%,#8bbdcf,transparent 70%),var(--canvas)}.sample-glassmorphism .sample-surface{background:#f3f8fce8;border:1px solid var(--border)}.sample-bubble .thumb-pill{border-radius:999px}.sample-bubble .sample-surface{border:1px solid var(--border)}.sample-neo-brutalism .sample-surface{border:2px solid var(--edge)}
`;
  window.UIKitStyles = {families,examples,miniatureCSS};
})();
